{"function":"async () => {
  const out = [];
  const els = ['#nome','#cpf','#servico','#unidade','#data-preferencial','#descricao','#documentos','.upload-button','#declaracao','.acao-enviar','#forma-video'];
  for (const s of els) {
    const e = document.querySelector(s);
    const before = getComputedStyle(e);
    const b = {o: before.outline, bs: before.boxShadow, bc: before.borderColor, bg: before.backgroundColor};
    e.focus();
    await new Promise(r=>setTimeout(r,50));
    const a = getComputedStyle(e);
    out.push({s, active: document.activeElement===e, fv: e.matches(':focus-visible'), before:b, after:{o:a.outline,bs:a.boxShadow,bc:a.borderColor,bg:a.backgroundColor}});
    e.blur();
  }
  return out;
}"}

